def transform4(grid):
    if not grid or not grid[0]:
        return grid

    rows, cols = len(grid), len(grid[0])
    output = [row[:] for row in grid]
    bg_color = grid[0][0]

    # Process both edges
    for edge_col in [0, cols-1]:
        for r in range(rows):
            c = edge_col
            # Check if this edge cell is bg
            if grid[r][c] == bg_color:
                # Check the interior neighbor
                if edge_col == 0:
                    interior_col = 1
                else:
                    interior_col = cols - 2

                if grid[r][interior_col] != bg_color:
                    # Interior neighbor is non-bg
                    # Check col thoroughly for non-bg
                    non_bg_rows = set(rr for rr in range(rows) if grid[rr][c] != bg_color)
                    if non_bg_rows:
                        output[r][c] = 1

    return output

